ALTER TABLE public.usuario_permissao_estado ADD COLUMN permissoes_legadas text[] NOT NULL DEFAULT '{}';
UPDATE public.usuario_permissao_estado e SET permissoes_legadas=(SELECT coalesce(array_agg(c.chave),'{}'::text[]) FROM public.permissao_catalogo c WHERE (public.has_role(e.user_id,'admin') OR public.has_role(e.user_id,'super_admin')) OR (c.pai IS NULL AND split_part(c.chave,'.',1) NOT IN ('usuarios','dados','integracoes','carteiras')) OR (public.has_role(e.user_id,'gerente') AND c.chave IN ('usuarios.visualizar','carteiras.visualizar','integracoes.visualizar','dados.visualizar','carteiras.alterar')) OR (c.chave IN ('anuncios.visualizar','perguntas.visualizar','publicidade.visualizar','promocoes.visualizar','mercado.visualizar','preco.alterar','publicidade.campanhas','publicidade.anuncios','promocoes.aplicar','promocoes.remover','perguntas.responder','integracoes.configurar') AND public.ml_e_consultor(e.user_id)) OR c.chave IN ('metas.alterar','relatorios.exportar','integracoes.conectar')) WHERE e.legado;
CREATE OR REPLACE FUNCTION public.is_super_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid()=ANY(ARRAY['fd93c492-0d67-47ff-b52d-b3ea2b61f041'::uuid,'c41be23f-bd64-4515-87f5-827f67f67927'::uuid,'81efb362-7cd2-4a55-b095-33056d5c6231'::uuid]) AND public.has_role(auth.uid(),'super_admin'); $$;
CREATE OR REPLACE FUNCTION public.usuario_tem_permissao(p_user_id uuid,p_permissao text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_user_id IS NOT NULL AND EXISTS(SELECT 1 FROM permissao_catalogo WHERE chave=p_permissao) AND ((p_user_id=ANY(ARRAY['fd93c492-0d67-47ff-b52d-b3ea2b61f041'::uuid,'c41be23f-bd64-4515-87f5-827f67f67927'::uuid,'81efb362-7cd2-4a55-b095-33056d5c6231'::uuid]) AND public.has_role(p_user_id,'super_admin')) OR EXISTS(SELECT 1 FROM usuario_permissao_estado WHERE user_id=p_user_id AND legado AND revisado_em IS NULL AND p_permissao=ANY(permissoes_legadas)) OR (EXISTS(SELECT 1 FROM usuario_permissoes WHERE user_id=p_user_id AND permissao=p_permissao) AND NOT EXISTS(SELECT 1 FROM permissao_catalogo c WHERE c.chave=p_permissao AND c.pai IS NOT NULL AND NOT EXISTS(SELECT 1 FROM usuario_permissoes WHERE user_id=p_user_id AND permissao=c.pai)))); $$;
CREATE OR REPLACE FUNCTION public.minhas_permissoes() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('master',public.is_super_admin(),'legado',coalesce((SELECT legado AND revisado_em IS NULL FROM usuario_permissao_estado WHERE user_id=auth.uid()),false),'revisado',EXISTS(SELECT 1 FROM usuario_permissao_estado WHERE user_id=auth.uid() AND revisado_em IS NOT NULL),'permissoes',coalesce((SELECT jsonb_agg(chave ORDER BY chave) FROM permissao_catalogo WHERE public.tem_permissao(chave)),'[]'::jsonb)); $$;
CREATE OR REPLACE FUNCTION public.proteger_categoria_master() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND NOT public.is_super_admin() THEN RAISE EXCEPTION 'Somente master altera categorias' USING ERRCODE='42501'; END IF; IF (CASE WHEN TG_OP='DELETE' THEN OLD.role='super_admin' WHEN TG_OP='UPDATE' THEN NEW.role='super_admin' OR OLD.role='super_admin' ELSE NEW.role='super_admin' END) THEN IF current_user IN ('authenticated','anon') THEN RAISE EXCEPTION 'Categoria master reservada' USING ERRCODE='42501'; END IF; IF TG_OP<>'DELETE' AND NEW.role='super_admin' AND NOT NEW.user_id=ANY(ARRAY['fd93c492-0d67-47ff-b52d-b3ea2b61f041'::uuid,'c41be23f-bd64-4515-87f5-827f67f67927'::uuid,'81efb362-7cd2-4a55-b095-33056d5c6231'::uuid]) THEN RAISE EXCEPTION 'Conta não pertence às masters confirmadas' USING ERRCODE='42501'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.checklist_escopo_loja(p_cust text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_super_admin() OR (EXISTS(SELECT 1 FROM usuario_permissao_estado WHERE user_id=auth.uid() AND legado AND revisado_em IS NULL) AND public.has_role(auth.uid(),'admin')) OR p_cust=ANY(public.get_allowed_cust_ids()); $$;
CREATE OR REPLACE FUNCTION public.guard_tema_ml(p_tema text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE p_tema WHEN 'vendas' THEN usuario_tem_alguma_permissao(ARRAY['resumo.visualizar','reputacao.visualizar','full.visualizar','publicidade.visualizar','correlacoes.visualizar']) WHEN 'visitas' THEN usuario_tem_alguma_permissao(ARRAY['resumo.visualizar','preco.visualizar','publicidade.visualizar','correlacoes.visualizar']) WHEN 'reputacao' THEN tem_permissao('reputacao.visualizar') WHEN 'envios' THEN tem_permissao('logistica.visualizar') WHEN 'ads' THEN usuario_tem_alguma_permissao(ARRAY['publicidade.visualizar','resumo.visualizar','correlacoes.visualizar']) WHEN 'anuncios' THEN usuario_tem_alguma_permissao(ARRAY['qualidade.visualizar','anuncios.visualizar','full.visualizar','promocoes.visualizar']) WHEN 'promocoes' THEN tem_permissao('promocoes.visualizar') WHEN 'perguntas' THEN usuario_tem_alguma_permissao(ARRAY['perguntas.visualizar','reputacao.visualizar']) ELSE false END; $$;